const row = $input.first().json;
const reasons = [];
const mins = [];
const i24Min = row.i24_last_ok ? Number(row.i24_minutes_since) : null;
const ebMin = row.eb_last_ok ? Number(row.eb_minutes_since) : null;
// ponytail: EB intake stopped 2026-07-15 (client paused EasyBroker). Flip true to re-enable EB staleness alert.
const EB_ENABLED = false;
const errCount = Number(row.recent_error_count || 0);
// i24 scraper only runs 08:00-20:00 MX; skip staleness outside window (+45m grace)
const i24Active = row.i24_active_window === true || row.i24_active_window === 'true';

if (i24Active && (i24Min === null || i24Min > 45)) {
  reasons.push(`Scraper i24: ${i24Min === null ? 'sin corridas ok registradas' : 'ultima ok hace ' + Math.round(i24Min) + ' min'} (umbral 45 min)`);
  mins.push(i24Min || 0);
}
if (EB_ENABLED && (ebMin === null || ebMin > 45)) {
  reasons.push(`Scraper EasyBroker: ${ebMin === null ? 'sin corridas ok registradas' : 'ultima ok hace ' + Math.round(ebMin) + ' min'} (umbral 45 min)`);
  mins.push(ebMin || 0);
}
if (errCount >= 3) {
  reasons.push(`${errCount} corridas con error/auth_error en la ultima hora`);
}

const alert = reasons.length > 0;
const worstMin = mins.length ? Math.max(...mins) : 0;
const subject = alert
  ? `⚠️ BYG: scraper sin corrida ok hace ${Math.round(worstMin)} min`
  : 'BYG watchdog: ok';
const body = reasons.map(r => `- ${r}`).join('<br>');

return [{ json: { alert, subject, body, i24Min, ebMin, errCount, i24Active } }];

