WITH unassigned AS (
  SELECT opportunity_id FROM public.routing_v2_ops_view WHERE is_unassigned
)
SELECT u.opportunity_id, a.alert_id, a.is_new, a.acknowledged
FROM unassigned u,
LATERAL public.record_unassigned_alert(u.opportunity_id, 'wf20-unassigned:' || u.opportunity_id::text) a;

